SELECT COUNT(dim_contract.version) AS n_versiones
FROM andes_viento_dev.gold.dim_contract
WHERE dim_contract.contract_id = 'PPA-2023-007';

SELECT COUNT(DISTINCT `client_name`) AS clientes_mineria
FROM `andes_viento_dev`.`gold`.`dim_contract`
WHERE `sector` ILIKE '%Minería%' AND `is_current` = true AND `client_name` IS NOT NULL AND `sector` IS NOT NULL;
